-- wave-clean-a-2026-10-08: 160 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('12-kitchen-and-wine', '0fe5a84a3cd0fde1bec825976bc302ec', 'An all-day restaurant and wine bar on Jalan Pantai Berawa, open 8am to midnight daily. Its own site describes grill cooking with local ingredients, a breakfast service and a large wine list. You can book through the website or WhatsApp, but you don''t have to.'),
    ('2-aces-massage-and-spa-seminyak', '765d914741afdc16b4ff3a2c337adddc', '2 Aces, a massage studio in Seminyak, does traditional massage.'),
    ('afterglow-bar-and-kitchen-at-tribe-bali-kuta-beach', '0d3cf7731881c2a0b7e373ce40233de1', 'Afterglow Bar and Kitchen is the rooftop restaurant at TRIBE Bali Kuta Beach, open daily from 07:00 to 23:00. It looks out over Kuta''s shoreline, and there is an infinity pool on the same rooftop.'),
    ('air-terjun-gitgit', '4cd45c9a51b0c783299e22d3ff729ce3', 'A multi-tier waterfall in Buleleng, on the mountain road between south Bali and Singaraja.'),
    ('aliya-salon-and-day-spa-canggu', '068cc5fce36f3a04193b4dc2f6c8bb4c', 'At Aliya, a salon and day spa in Canggu, the full body massage is 195K IDR for 60 minutes. The list covers traditional massage and reflexology, and you book through Fresha.'),
    ('alma-tapas-bar', '624592c7641468173388ca99faa0d794', 'A Spanish tapas bar on Jalan Pantai Berawa, serving from 3pm daily, with food until 10.30pm and drinks until 11.30pm. The February 2026 menu goes from jamon and charcuterie to plancha seafood, beef cheeks and tartares, with separate wine and bar lists. A second Alma is at Pantai Bingin in Uluwatu.'),
    ('amandari-ubud', '7ecd2433dfd27df533b5628bfafb24bf', 'The spa at Amandari in Ubud lists Balinese massage, booked through Amandari''s website.'),
    ('amplitude-skate-and-bike-park', '4313e76b86862beee4695765155ab513', 'A 3000 square metre concrete skatepark in Kerobokan. It has a street course and a bowl park with three bowls, the largest an Olympic-size 10ft. Its own site welcomes skateboards, kickboards, cruisers and inline skates. The on-site school runs 1.5-hour group and private lessons from age four, boards included.'),
    ('anandinii-sidemen', '6450cbb93dc1daa2d212d1a1f2a3cfd0', 'A 60-minute Balinese massage costs 300K IDR at Anandinii, a massage studio in Sidemen. Book on the studio''s own site.'),
    ('anantara-ubud-bali-resort-ubud', '2f914474845a9f920b078c19a3ed0da1', 'Thai massage at Anantara Ubud Bali Resort''s day spa includes the Thai Warrior Stretching Massage, 2850K IDR for 60 minutes. Bookings go through the resort''s website.'),
    ('ankhusa-restaurant-ubud-by-wonderspace', '1fd350c736b1d07b0d639caf9a25f0f2', 'Ankhusa is the restaurant at Aksari Resort in Kenderan, north of Ubud. The menu is Balinese, Indonesian and international: roast duck, chicken satay, nasi goreng, oxtail. Royal Dining is a shared Balinese megibung feast. Outdoor tables face the jungle.'),
    ('aperitif-restaurant', 'acb35db5e1c07f0c32d1ca2cbbd225e7', U&'Ap\00E9ritif is a degustation restaurant in Petulu, near Ubud, where the cooking mixes French, Japanese and Indonesian influences.'),
    ('avli-bali', 'ebd87cc37d025e7192c3d3ac99d4dadf', 'AVLI is a modern Greek restaurant in Pecatu with an open-air courtyard. Greek chef Angelos Lantos runs the kitchen, which sends out sharing plates of pita, dips, grilled meats and seasonal seafood.'),
    ('ayam-betutu-khas-gilimanuk', '1d921cde9f572bd907188520a2b57157', 'A Denpasar kitchen that specialises in ayam betutu: Gilimanuk-style chicken slow-cooked in Balinese spice paste until it falls off the bone. It is a focused, no-frills local place where the betutu and the sambals are the reason to come.'),
    ('babi-guling-swari', 'a0bc26b2cbb1687da22f2c3e511a9b09', 'Warung Babi Guling Swari serves Balinese roast pork with crispy skin and bumbu genep. Its official links list a Canggu branch and ordering through GrabFood, GoFood and ShopeeFood.'),
    ('bahari-balinese-spa-spa-nusa-dua', '0d41025653b240cf3c06636850073a3f', 'Bahari Balinese Spa is a Nusa Dua day spa that does head massage. Its Head To Toes treatment runs 90 minutes for 350K IDR, and you can book on its website.'),
    ('bali-beach-hotel-fitness-centre', '33a8fd8c633d0d608f7e56cc4df258b1', 'A new 24-hour fitness centre at Bali Beach Hotel in north Sanur, free for hotel guests. The room is large and well equipped, and the property is built around a 57 by 37 metre beachfront pool facing the Indian Ocean.'),
    ('bali-beach-hotel-yoga-wellness', '7a9f2ca7e3c3a687405ecbef4795d6f1', 'Bali Beach Hotel in north Sanur runs sunrise yoga at 06:00, and its Taru Pramana Spa & Wellness is open 09:00-21:00. The main pool measures 57 by 37 metres and faces Sanur Beach.'),
    ('bali-padel-academy', '01deb5337f28e821caca3905b4da07ad', 'A padel centre on Jalan Babakan Kubu in Canggu, open 7am to 11pm daily except Nyepi. Courts book through the Playtomic app, and there are one-hour coached lessons and a recovery area with a sauna and ice bath. Its own site calls it the international headquarters of the NOX Future Academy.'),
    ('bali-reflexology-tabanan', 'cc627104fec9233bf276bde6ff017fab', 'In Tabanan, Bali Reflexology is a wellness spa with Balinese massage on offer.'),
    ('bali-tropic-resort-nusa-dua', 'f73c863aa3789b5e2a6376d36de53323', 'Bali Tropic Resort''s wellness spa in Nusa Dua does traditional massage, and a 60-minute Warm Herbal Pouch Massage costs 618K IDR.'),
    ('bali-yoga-school-ubud', 'd696ef9f50974dd974f843a5c1d0cced', 'Bali Yoga School in Ubud offers Ayurvedic treatment.'),
    ('balumba-surf-school-uluwatu', 'd562202555496363c9d35c9a0968db0b', 'A surf school that teaches at Uluwatu''s breaks: Dreamland, Padang Padang and Balangan.'),
    ('bambou-cafe-and-lagree-cemagi', 'a864904f296d0a7403ef3b21f630ee67', 'A cafe on Jl. Pantai Mengening in Cemagi for coffee, brunch and dinner, with a Lagree reformer studio on site. On Instagram the venue is Coffee & Lagree; the studio trades as Kysko Studio Bali and takes class bookings through ClassPass. The cafe takes walk-ins and phone bookings.'),
    ('bebek-tepi-sawah', '157e40c8ff1003c806539d816f500a0e', 'A rice-field restaurant in Teges, Peliatan, built around crispy duck. The setting is traditional Balinese.'),
    ('bella-by-sage', '7a230ec4c3a0f9f4791d991faa66a145', 'A vegan kitchen in Penestanan doing pizzas, pastas and salads, with gluten-free diets catered for.'),
    ('bella-canggu', 'e985ba4bc1f33934e5d382c09cb89819', 'Bella''s kitchen in Canggu is contemporary Mediterranean and Middle Eastern. ''Geisha'' and ''Kopi Martini'' are both on the menu, and you can book online.'),
    ('bella-italia-sanur', 'd124c5ef9991552c8a638bd37625595d', 'An Italian restaurant on Jalan Cemara in Sanur Kauh. Expect wood-fired pizza, homemade pasta and Italian desserts, with vegetarian options.'),
    ('boheme-canggu', 'c2e7b82babc62fae59ff0c1dc83deda8', 'The all-day restaurant and bar at Shore Amora Canggu on Jl. Pantai Pererenan, open 7am-10pm daily to hotel and day guests. The Western menu uses local, seasonal produce, with vegan, gluten-free and lactose-free options. Next to it are an infinity pool with daybeds and an air-conditioned coworking space open until 10pm.'),
    ('bokashi-berawa', 'b3cb2f3dca5c507ad059e4919c65ffb4', 'A cafe and teahouse above the Bokashi organic grocery store on Jl. Subak Sari in Berawa, with about 30 seats. The food is Japanese-leaning brunch, bento, soba and donburi, with single-origin Indonesian teas and matcha to drink. The group''s Pererenan branch is closed until further notice.'),
    ('brie-restaurant-and-cheesery', '709e29a3d256487dbf7bf0c14ac94ffd', 'A restaurant with its own cheesery. Milk comes from the group''s farm in Java and becomes cheese within twelve hours, five times a week. Cheese board, truffle tagliatelle, brie burger and house burrata. The open kitchen is downstairs, the bar above.'),
    ('caffe-torino-by-venticinque-group-at-grand-srikandi-mansion', '1b56a1bcd9c6bd1cc8db453f38a6a0a2', 'An Italian cafe and restaurant from the Venticinque Group, inside Grand Srikandi Mansion on Jl. Cepaka Utama in Dalung, inland from the Canggu coast. Its Chope listing describes rice-field views and an all-day menu, from breakfast panini to cured-meat boards and pasta.'),
    ('casa-de-lokha-mexican-grill-and-fusion-the-lokha-ubud', '330ed7277547de9419b632dc7bdd1754', 'Casa de Lokha is the Mexican grill and fusion restaurant at The Lokha Ubud in Keliki. Its current offer is Tacos Tuesday, and the resort runs a separate two-for-one cocktail programme.'),
    ('celebrity-fitness', 'a41d575ab5754829ca91187b862a6b13', 'An international gym chain at Lippo Plaza on Sunset Road. A full floor with a cycling studio, pilates, free weights and cardio, plus personal training and group classes. Membership tiers run from a single club to access across the chain abroad.'),
    ('celestine-spa-kuta-legian', 'b2bb06701c9fbf2cb8a1ad0660130e2b', 'Celestine is a spa in Legian that takes bookings by WhatsApp.'),
    ('chaskaa-modern-indian-cuisine-and-bar-at-jimbaran', 'ac2fa42b9fc1a9ad9c9f6289f27bdb3c', 'Restaurant on Uluwatu St, open daily 11:00am-11:30pm.'),
    ('chill-reflexology-seminyak', 'e287be87b0a9c1ee62059fc11f2c6b02', 'Chill Reflexology is a reflexology studio in Seminyak.'),
    ('cocomo-at-canggu', '5ec286b1e5c3dbc24362bd17ad0c915f', 'An island bistro on Jl. Pantai Batu Bolong, a short way back from the shoreline, serving seafood and grilled dishes. Its Chope listing says it recently turned into a seafood-led coastal bistro. It is open 11:00-23:00 daily, with a lunch sitting until 5pm and dinner from 5pm.'),
    ('crumb-and-coaster-kuta', '961ebe8f2ea348e710ecc863c4a031ff', 'A Kuta breakfast spot whose menu mixes Indonesian dishes with pasta and Thai curry. There is a wide coffee list, hot and cold.'),
    ('d-made-restaurant-the-kalyana-ubud-resort', '395fc711388a5bc9444e9e3364277215', 'D''Made is The Kalyana Ubud Resort''s 26-seat restaurant in Mas, serving Indonesian and Balinese food beside the pool and the greenery around it. It is open daily from 07:00 to 23:00.'),
    ('desa-wisata-besakih', '29f4d987bbdd394e478e302043f52f25', 'A temple complex on the slopes of Mount Agung in Rendang, Karangasem. A single foreigner ticket bundles a local guide, sarong and shuttle up to the gate.'),
    ('desa-wisata-bugbug', '3c20d40400386d500d1dd9294bd86605', 'A traditional (desa adat) village on the coast near Candidasa, with ceremonial traditions held through the year. The nearby Bukit Asah hilltop looks out over Pulau Kuan, a small whale-shaped island just offshore.'),
    ('desa-wisata-gitgit', '48d58ac524e97674172b9248817cd57e', 'The village at the foot of the Gitgit waterfall, on the mountain road between south Bali and Singaraja in Buleleng.'),
    ('desa-wisata-sanur-kauh', '9486a568596b0dbfbdd42703bf20dc82', 'A village in South Denpasar on Mertasari beach, with white sand and calm water. The beach faces north, so it catches both sunrise and sunset. On the sand, Pura Dalam Pengembak Mertasari is used for melukat purification bathing.'),
    ('dua-umalas-seminyak', '0b2b6da02d7052b4c724bd9109dd6d1c', 'Wet scrambled eggs and pumpkin ginger soup share the menu at Dua Umalas, a Seminyak restaurant cooking local and Western food. Bookings are by WhatsApp.'),
    ('empower-balance-tabanan', '042c461a66c96651fd9d9ef64b82a90f', 'Yoga is on the menu at Empower Balance, a wellness spa in Tabanan.'),
    ('eskq-bar-steak-house', '856e89fbeba0010b4c947a69cd1d2db7', 'A steakhouse and wine bar on Jl. Raya Babakan with a list of 50+ wines. Wood-fired cuts go from Australian grain-fed skirt and picanha to a pre-order Tomahawk, and there is Italian pasta and risotto. The kitchen runs 6pm to 2am, Tuesday to Sunday, with live jazz on Fridays.'),
    ('flourish', '9f5abf2be259644898698ecc382a54a0', 'A healthy restaurant on Nyuh Kuning Rd in central Ubud that markets itself on gluten-free and vegan food.'),
    ('fresh-spa-ubud', '298d38f6382e6aba0f3a03dac9df3cc1', 'Fresh! Spa, a day spa in Ubud, does foot massage.'),
    ('galangal-spa-nusa-dua', '641683a3b066da01cf8bed9c036bcc1e', 'Galangal Spa takes WhatsApp bookings for traditional massage in Nusa Dua.'),
    ('gather-canggu', 'd77dad97b993de74d844424991648cbe', 'Gather is a breakfast and brunch restaurant in Canggu, and you book a table by WhatsApp. The menu has The Classic Brekkie, The Avo Set and The Gather Plate.'),
    ('glow-spa-mandira-kuta-legian', 'dd7b0cb36ba692ee1a6df2d2b492dc16', 'Glow Spa Mandira in Legian charges 100K IDR for a 60-minute Traditional Balinese Aromatherapy Massage. The day spa does both Balinese and traditional massage.'),
    ('grillos-cafe-and-eatery', '0ca59e7834d3b0f77685cf6812a942e7', 'A cafe and coffee shop on Jl. Veteran at Buduk, inland from Canggu in Mengwi, open 07:00-23:00 daily. Its own Grab listing describes the kitchen as Western cooking with Eastern flavours.'),
    ('herb-library', '4187760ad6ac7612843513a80717b852', 'Herb Library is an all-day spot on Jl. Jembawan in Ubud, with plant-based dishes and responsibly sourced fish and chicken.'),
    ('hidden-gem-uluwatu-uluwatu-bukit', '8e97d645fa24459a70775c369f825d74', 'Hidden Gem Uluwatu cooks California-inspired food in the Bukit: tuna tartare, crispy soft shell tacos in three colours and a warm chocolate lava cake. Tables are booked through Chope.'),
    ('home-cafe-mengwi', '2c4aa8ee784909ae0a3e005b07fcde02', 'A brunch cafe in Tiying Tutul, Pererenan. It describes its own cooking as healthy.'),
    ('imbu-restaurant-the-kemilau-ubud', '151bc37dab311fab9b6f7913a7c13af8', 'IMBU is an open-layout restaurant at The Kemilau Ubud on Jalan Raya Pengosekan, seating up to 100. Dishes such as tuna yukhoe and cured salmon sit next to slow-cooked beef and regional Indonesian flavours.'),
    ('intercontinental-bali-resort-fitness-centre', 'c680c9eca1b00cd4171738c68531384d', 'InterContinental Bali Resort in Jimbaran has a 24-hour fitness centre, a jogging track through the grounds, tennis courts and six pools. Personal training is available, and Pencak Silat martial-arts sessions are on the activity list.'),
    ('intercontinental-bali-resort-yoga', 'a1a2cf16e151bba8006aff861b04c9c9', 'Yoga at InterContinental Bali Resort in Jimbaran happens in the 24-hour fitness centre and outdoors by the sea, with morning and sunset groups. A yoga instructor is available to guests.'),
    ('intuitive-flow', '4ac73750bcd4502ceb45ce9deeadaf4f', 'A Penestanan studio whose glass-walled, open-air shala sits above the rice fields, reached by the hillside footpath near Alchemy.'),
    ('jatiluwih', 'a32c5db34d09c743568858294f91121d', 'UNESCO-listed subak (traditional irrigation) rice terraces at roughly 700 metres altitude in Tabanan.'),
    ('jungle-flower-restaurant', '2da491e574e5f7af3263e787ddba332d', 'The restaurant inside Jungle Flower Villas, in a jungle setting at Lodtunduh, south of central Ubud. It has been open since 2024.'),
    ('kafe-ubud', '099d1db7b73711d7d8821aadeec687a9', 'The menu at Kafe in Ubud is varied and international, with Meg''s Big Salad Bowl and a Kale Detox Salad on it. Its website takes bookings.'),
    ('karsa-cafe', '56375676315198c0765fa931b3f1924b', U&'A caf\00E9 in the rice paddies and jungle valley along the Campuhan Ridge Walk. It serves organic meals, seasonal fruit smoothies and coffee, with open green views.'),
    ('kekeb-restaurant-nusa-dua', 'ca56e4daf99aa710a3c815d65a0d37a6', 'Kekeb in Nusa Dua is an Indonesian and Balinese restaurant that also does seafood. Chicken betutu, sate and a rendang package are on the menu, and WhatsApp is how you book.'),
    ('ku-de-ta', '1a33c1da25384ab6705af7790e1fbaaf', 'A beachfront club right on the sand at Seminyak Beach. It runs from morning through sunset into late night, with dining, a bar, a pool and daybeds. It is an all-day beach club and restaurant rather than a quick stop.'),
    ('kush-day-spa-ubud', 'd19e6cd980f0cfc4150d5645109b7afe', 'Kush is a day spa in Ubud with Ayurvedic treatment.'),
    ('la-joya-uluwatu-bukit', '08f267efdcb138f65d08b995520faf27', 'La Joya, a resort spa in the Bukit, does a couple massage, and you book on its own site.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 68 then raise exception 'wave-clean-a-2026-10-08 why_its_here: expected 68 rows, got %', n; end if;

  update venues v set best_for = d.val
  from (values
    ('12-kitchen-and-wine', 'cfab2453bb41672a6e1f1671f4322ad7', 'A date or an unhurried dinner over wine'),
